'use client';
import { useCallback, useEffect, useId, useState } from 'react';
import { useStudioMotion } from '../../motion';
import { StudioCanvas } from '../../three';
import type { EffectProps } from '../../types';
import { ExplodedDrawing } from './fallback';
import { PARTS, type PartId } from './parts';
import { Scene } from './scene';
import styles from './styles.module.css';

type Params = { amount: number; spread: number; stagger: number; accent: string };

function Ready({ onChange }: { onChange: (ready: boolean) => void }) {
  useEffect(() => { onChange(true); return () => onChange(false); }, [onChange]);
  return null;
}

export default function ExplodedView({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const [amount, setAmount] = useState(params.amount);
  const [smooth, setSmooth] = useState(0.12);
  const [scenePart, setScenePart] = useState<PartId | null>(null); // pointer over a part in 3D
  const [rowPart, setRowPart] = useState<PartId | null>(null); // row hovered or focused
  const [pinned, setPinned] = useState<PartId | null>(null);
  const [ready, setReady] = useState(false);
  useEffect(() => setAmount(params.amount), [params.amount]);
  const highlight = scenePart ?? rowPart ?? pinned;
  const name = PARTS.find((p) => p.id === highlight)?.name ?? null;

  const glideTo = useCallback((v: number) => { setSmooth(0.45); setAmount(v); }, []);
  const pick = useCallback((id: PartId) => setPinned((p) => (p === id ? null : id)), []);

  return (
    <div className={styles.root} style={{ ['--xv-accent' as string]: params.accent }}>
      <div className={styles.viewport}>
        <StudioCanvas
          label="Compact camera, exploded view"
          description="A procedural compact camera in seven parts: body shell, top plate with shutter dial, leather front grip, lens mount, lens barrel with an accent ring, front glass element and battery. The separation slider moves the parts apart along their own directions, one after another."
          camera={{ fov: 30, near: 0.1, far: 80, position: [-4, 3, 4.5] }}
          fallback={<ExplodedDrawing amount={amount} spread={params.spread} stagger={params.stagger} highlight={highlight} accent={params.accent} />}
        >
          <Ready onChange={setReady} />
          <Scene amount={amount} smooth={smooth} spread={params.spread} stagger={params.stagger} accent={params.accent} highlight={highlight} cut={reduced} onHover={setScenePart} onPick={pick} />
        </StudioCanvas>
        <p className={styles.tag} aria-hidden="true">{name ?? 'Compact camera · sample assembly'}</p>
      </div>

      <div className={styles.panel}>
        <div className={styles.sliderRow}>
          <label htmlFor={`${uid}-amt`} className={styles.kicker}>Separation</label>
          <output htmlFor={`${uid}-amt`} className={styles.value}>{Math.round(amount * 100)}%</output>
        </div>
        <input
          id={`${uid}-amt`}
          type="range" min={0} max={1} step={0.01} value={amount}
          className={styles.slider}
          onChange={(e) => { setSmooth(0.12); setAmount(Number(e.target.value)); }}
        />
        <div className={styles.buttons}>
          <button type="button" onClick={() => glideTo(0)} disabled={amount === 0}>Assemble</button>
          <button type="button" onClick={() => glideTo(1)} disabled={amount === 1}>Explode</button>
        </div>
        <p className={styles.kicker} id={`${uid}-parts`}>Parts</p>
        <ol className={styles.list} aria-labelledby={`${uid}-parts`}>
          {PARTS.map((p, i) => (
            <li key={p.id}>
              <button
                type="button"
                className={styles.row}
                data-hot={highlight === p.id || undefined}
                aria-pressed={pinned === p.id}
                onPointerEnter={() => setRowPart(p.id)}
                onPointerLeave={() => setRowPart(null)}
                onFocus={() => setRowPart(p.id)}
                onBlur={() => setRowPart(null)}
                onClick={() => pick(p.id)}
              >
                <span className={styles.num} aria-hidden="true">{String(i + 1).padStart(2, '0')}</span>
                <span className={styles.rowText}>
                  <span className={styles.rowName}>{p.name}</span>
                  <span className={styles.rowMat}>{p.material}</span>
                </span>
              </button>
            </li>
          ))}
        </ol>
        <p className={styles.hint}>
          {ready
            ? 'Hover or focus a part to light it up; point at the model to find a part in the list. Click to pin the highlight.'
            : 'Interactive 3D is unavailable, so a flat diagram follows the slider instead.'}
        </p>
      </div>
    </div>
  );
}

import { CanvasTexture, SRGBColorSpace } from 'three';

/** Soft radial floor shadow, drawn once. */
export function blobTexture(): CanvasTexture | null {
  if (typeof document === 'undefined') return null;
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const g = c.getContext('2d');
  if (!g) return null;
  const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grad.addColorStop(0, 'rgba(16,13,10,0.8)');
  grad.addColorStop(0.5, 'rgba(16,13,10,0.3)');
  grad.addColorStop(1, 'rgba(16,13,10,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 128, 128);
  const t = new CanvasTexture(c);
  t.colorSpace = SRGBColorSpace;
  return t;
}

'use client';
/**
 * No-WebGL fallback: a flat exploded diagram of the same assembly. The slider still drives it (same staggered
 * progress function), and part rows still highlight their part — only the third dimension is missing.
 */
import { COLORS, PARTS, partProgress, type PartId } from './parts';

/** Screen offset (px at full separation, spread 1) for each part in the 480 × 320 drawing. */
const OFFSET: Record<PartId, [number, number]> = {
  glass: [128, 34], barrel: [86, 22], mount: [44, 11], top: [0, -64], grip: [-78, 8], battery: [0, 74], body: [0, 0],
};

export function ExplodedDrawing({ amount, spread, stagger, highlight, accent }: { amount: number; spread: number; stagger: number; highlight: PartId | null; accent: string }) {
  const at = (id: PartId) => {
    const p = PARTS.find((x) => x.id === id)!;
    const t = partProgress(p.order, amount, stagger) * spread;
    return `translate(${(OFFSET[id][0] * t).toFixed(1)} ${(OFFSET[id][1] * t).toFixed(1)})`;
  };
  const hot = (id: PartId) => (highlight === id ? { stroke: accent, strokeWidth: 3 } : { stroke: '#11110f', strokeOpacity: 0.35, strokeWidth: 1 });
  return (
    <svg viewBox="0 0 480 320" role="img" aria-label="Exploded diagram of the compact camera: lens elements move forward, the top plate lifts, the grip slides off to the side and the battery drops out of the body." style={{ width: 'min(100%, 560px)', height: 'auto', maxHeight: 'calc(100% - 56px)' }}>
      <ellipse cx="250" cy="300" rx="170" ry="9" fill="#11110f" opacity="0.12" />
      <g transform={at('battery')}><rect x="168" y="178" width="84" height="26" rx="4" fill={COLORS.battery} {...hot('battery')} /></g>
      <g transform={at('body')}><rect x="140" y="122" width="200" height="110" rx="12" fill={COLORS.leatherette} {...hot('body')} /></g>
      <g transform={at('grip')}><rect x="150" y="130" width="34" height="94" rx="7" fill={COLORS.grip} {...hot('grip')} /></g>
      <g transform={at('top')}>
        <rect x="142" y="108" width="196" height="16" rx="5" fill={COLORS.alu} {...hot('top')} />
        <rect x="270" y="98" width="38" height="12" rx="3" fill={COLORS.alu} {...hot('top')} />
        <rect x="314" y="100" width="12" height="8" rx="2" fill={accent} />
      </g>
      <g transform={at('mount')}><circle cx="262" cy="176" r="46" fill={COLORS.steel} {...hot('mount')} /><circle cx="262" cy="176" r="36" fill="#2b2a27" /></g>
      <g transform={at('barrel')}><circle cx="262" cy="176" r="41" fill={COLORS.anodised} {...hot('barrel')} /><circle cx="262" cy="176" r="38" fill="none" stroke={accent} strokeWidth="3" /></g>
      <g transform={at('glass')}>
        <circle cx="262" cy="176" r="31" fill={COLORS.glass} {...hot('glass')} />
        <path d="M246 164a20 20 0 0 1 18-8" fill="none" stroke="#e9eef0" strokeOpacity="0.55" strokeWidth="3" strokeLinecap="round" />
      </g>
    </svg>
  );
}

/**
 * The compact camera assembly as data: each part's name, what it is made of, the direction it leaves in, how far,
 * and its place in the stagger. Shared by the WebGL scene and the SVG fallback.
 */
export type PartId = 'body' | 'top' | 'grip' | 'mount' | 'barrel' | 'glass' | 'battery';
export interface Part { id: PartId; name: string; material: string; dir: [number, number, number]; distance: number; order: number }

export const PARTS: readonly Part[] = [
  { id: 'glass', name: 'Front element', material: 'Coated optical glass', dir: [0, 0, 1], distance: 2.3, order: 0 },
  { id: 'barrel', name: 'Lens barrel', material: 'Anodised aluminium, accent ring', dir: [0, 0, 1], distance: 1.55, order: 1 },
  { id: 'mount', name: 'Lens mount', material: 'Machined steel bayonet', dir: [0, 0, 1], distance: 0.8, order: 2 },
  { id: 'top', name: 'Top plate', material: 'Brushed aluminium, shutter dial', dir: [0, 1, 0], distance: 1.0, order: 3 },
  { id: 'grip', name: 'Front grip', material: 'Leather over cork', dir: [-1, 0, 0.35], distance: 1.0, order: 4 },
  { id: 'battery', name: 'Battery', material: 'Lithium cell, keyed housing', dir: [0, -1, 0], distance: 1.2, order: 5 },
  { id: 'body', name: 'Body shell', material: 'Die-cast chassis in leatherette', dir: [0, 0, 0], distance: 0, order: 6 },
];

const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);

/** Per-part progress for the global amount: parts leave one after another (stagger = share of the range spent waiting). */
export function partProgress(order: number, amount: number, stagger: number, movers = 6): number {
  const delay = movers > 1 ? (Math.min(order, movers - 1) / (movers - 1)) * stagger : 0;
  return easeInOut(Math.min(1, Math.max(0, (amount - delay) / Math.max(0.05, 1 - stagger))));
}

export const COLORS = {
  leatherette: '#2c2926',
  alu: '#cfcbc3',
  steel: '#9d9a94',
  anodised: '#1d1c1a',
  glass: '#10171a',
  grip: '#73452a',
  battery: '#474a50',
};

'use client';
import { useFrame, useThree, type ThreeEvent } from '@react-three/fiber';
import { useEffect, useMemo, useRef } from 'react';
import {
  CylinderGeometry, Group, MeshBasicMaterial, MeshStandardMaterial, NeutralToneMapping, PlaneGeometry, TorusGeometry, Vector3,
  type BufferGeometry, type PerspectiveCamera,
} from 'three';
import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
import { LightingRig, type LightingPreset } from '../../three';
import { blobTexture } from './blob';
import { COLORS, PARTS, partProgress, type PartId } from './parts';

const FRONT = 0.425; // body front face (z)
const LENS: [number, number] = [0.25, -0.05]; // lens axis (x, y)

const LIGHT: LightingPreset = {
  label: 'Product rim', description: 'Soft key, cool fill and a strong rim so dark parts read on any stage.', exposure: 1.05,
  ambient: { color: '#ffffff', intensity: 0.22 },
  key: { color: '#fff4e6', intensity: 2.2, position: [-3, 5, 4] },
  fill: { color: '#dfe7ff', intensity: 0.6, position: [5, 2, 3] },
  rim: { color: '#ffffff', intensity: 2.6, position: [1, 3, -6] },
  env: { room: '#26231f', intensity: 0.75, panels: [
    { color: '#ffffff', intensity: 8, position: [0, 6, 1], size: [7, 5] },
    { color: '#ffeedd', intensity: 5, position: [-6, 2, 3], size: [1.4, 6] },
    { color: '#e6eeff', intensity: 4, position: [6, 2.5, -2], size: [1.2, 6] },
  ] },
};

interface Mesh { geo: BufferGeometry; mat: MeshStandardMaterial; pos?: [number, number, number]; rot?: [number, number, number] }
interface Built { id: PartId; base: [number, number, number]; meshes: Mesh[] }

function ToneMapping() {
  const gl = useThree((s) => s.gl);
  const invalidate = useThree((s) => s.invalidate);
  useEffect(() => { const prev = gl.toneMapping; gl.toneMapping = NeutralToneMapping; invalidate(); return () => { gl.toneMapping = prev; }; }, [gl, invalidate]);
  return null;
}

export interface SceneProps {
  amount: number;
  smooth: number;
  spread: number;
  stagger: number;
  accent: string;
  highlight: PartId | null;
  cut: boolean;
  onHover: (id: PartId | null) => void;
  onPick: (id: PartId) => void;
}

export function Scene({ amount, smooth, spread, stagger, accent, highlight, cut, onHover, onPick }: SceneProps) {
  const camera = useThree((s) => s.camera) as PerspectiveCamera;
  const aspect = useThree((s) => s.size.width / Math.max(1, s.size.height));
  const invalidate = useThree((s) => s.invalidate);
  const dom = useThree((s) => s.gl.domElement);
  const groups = useRef(new Map<PartId, Group>());
  const anim = useRef({ value: -1, vel: 0 });
  const tmp = useMemo(() => ({ dir: new Vector3(-0.6, 0.44, 0.67).normalize(), target: new Vector3(), pos: new Vector3() }), []);

  const res = useMemo(() => {
    const m = (color: string, roughness: number, metalness = 0) => new MeshStandardMaterial({ color, roughness, metalness });
    const blob = blobTexture();
    const geos = {
      body: new RoundedBoxGeometry(2.5, 1.45, 0.85, 4, 0.12),
      plate: new RoundedBoxGeometry(2.46, 0.14, 0.8, 3, 0.05),
      dial: new CylinderGeometry(0.22, 0.22, 0.1, 40),
      button: new CylinderGeometry(0.075, 0.075, 0.07, 24),
      grip: new RoundedBoxGeometry(0.52, 1.18, 0.16, 3, 0.06),
      mount: new CylinderGeometry(0.53, 0.53, 0.1, 56, 1, true),
      lip: new TorusGeometry(0.5, 0.035, 10, 56),
      barrel: new CylinderGeometry(0.46, 0.48, 0.75, 56),
      ring: new TorusGeometry(0.465, 0.022, 8, 56),
      glass: new CylinderGeometry(0.37, 0.37, 0.05, 56),
      battery: new RoundedBoxGeometry(0.95, 0.3, 0.5, 2, 0.04),
      floor: new PlaneGeometry(1, 1),
    };
    const parts: Built[] = [
      { id: 'body', base: [0, 0, 0], meshes: [{ geo: geos.body, mat: m(COLORS.leatherette, 0.88) }] },
      { id: 'top', base: [0, 0.8, 0], meshes: [
        { geo: geos.plate, mat: m(COLORS.alu, 0.34, 1) },
        { geo: geos.dial, mat: m(COLORS.alu, 0.28, 1), pos: [0.62, 0.12, 0] },
        { geo: geos.button, mat: m(accent, 0.45), pos: [0.98, 0.1, 0.2] },
      ] },
      { id: 'grip', base: [-0.82, -0.02, FRONT + 0.08], meshes: [{ geo: geos.grip, mat: m(COLORS.grip, 0.7) }] },
      { id: 'mount', base: [LENS[0], LENS[1], FRONT + 0.05], meshes: [
        { geo: geos.mount, mat: m(COLORS.steel, 0.3, 1), rot: [Math.PI / 2, 0, 0] },
        { geo: geos.lip, mat: m(COLORS.steel, 0.3, 1), pos: [0, 0, 0.05] },
      ] },
      { id: 'barrel', base: [LENS[0], LENS[1], FRONT + 0.1 + 0.375], meshes: [
        { geo: geos.barrel, mat: m(COLORS.anodised, 0.42, 0.55), rot: [Math.PI / 2, 0, 0] },
        { geo: geos.ring, mat: m(accent, 0.5), pos: [0, 0, 0.3] },
      ] },
      { id: 'glass', base: [LENS[0], LENS[1], FRONT + 0.1 + 0.75 + 0.03], meshes: [{ geo: geos.glass, mat: m(COLORS.glass, 0.04, 0.3), rot: [Math.PI / 2, 0, 0] }] },
      { id: 'battery', base: [-0.5, -0.42, 0], meshes: [{ geo: geos.battery, mat: m(COLORS.battery, 0.5, 0.2) }] },
    ];
    const floor = new MeshBasicMaterial({ map: blob, transparent: true, depthWrite: false, toneMapped: false, opacity: 0.32 });
    return { parts, geos, floor, blob, accented: [parts[1].meshes[2].mat, parts[4].meshes[1].mat] };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps -- accent is applied below
  useEffect(() => () => {
    for (const p of res.parts) for (const x of p.meshes) x.mat.dispose();
    for (const g of Object.values(res.geos)) g.dispose();
    res.floor.dispose();
    res.blob?.dispose();
  }, [res]);
  useEffect(() => { for (const mat of res.accented) mat.color.set(accent); invalidate(); }, [accent, res, invalidate]);

  // Emissive lift on the highlighted part (always paired with the part name in the DOM).
  useEffect(() => {
    for (const p of res.parts) for (const x of p.meshes) {
      const on = p.id === highlight;
      x.mat.emissive.set(on ? accent : '#000000');
      x.mat.emissiveIntensity = on ? 0.42 : 0;
    }
    invalidate();
  }, [highlight, accent, res, invalidate]);

  useEffect(() => { invalidate(); }, [amount, spread, stagger, aspect, invalidate]);

  useFrame((_, rawDt) => {
    const a = anim.current;
    const dt = Math.min(rawDt, 1 / 20);
    if (a.value < 0 || cut) { a.value = amount; a.vel = 0; }
    else if (a.value !== amount) {
      // Critically damped follow: the slider stays responsive, the buttons glide.
      const omega = 2 / Math.max(0.02, smooth);
      const x = omega * dt, exp = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x);
      const change = a.value - amount, temp = (a.vel + omega * change) * dt;
      a.vel = (a.vel - omega * temp) * exp;
      a.value = amount + (change + temp) * exp;
      if (Math.abs(a.value - amount) < 2e-4 && Math.abs(a.vel) < 2e-3) { a.value = amount; a.vel = 0; }
      else invalidate();
    }
    for (const p of PARTS) {
      const g = groups.current.get(p.id);
      const built = res.parts.find((b) => b.id === p.id);
      if (!g || !built) continue;
      const t = partProgress(p.order, a.value, stagger);
      g.position.set(built.base[0] + p.dir[0] * p.distance * spread * t, built.base[1] + p.dir[1] * p.distance * spread * t, built.base[2] + p.dir[2] * p.distance * spread * t);
    }
    // Frame the assembly: step back (and towards the lens) as it opens; narrow canvases step back further.
    const e = a.value * spread;
    const d = (7.2 + 4.4 * e) * Math.min(2, Math.max(1, 1.3 / aspect));
    tmp.target.set(0.2 + 0.35 * e, -0.05, 0.3 + 1.2 * e);
    camera.position.copy(tmp.pos.copy(tmp.dir).multiplyScalar(d).add(tmp.target));
    camera.lookAt(tmp.target);
  });

  const over = (id: PartId) => (e: ThreeEvent<PointerEvent>) => { e.stopPropagation(); dom.style.cursor = 'pointer'; onHover(id); };
  const out = () => { dom.style.cursor = ''; onHover(null); };
  useEffect(() => () => { dom.style.cursor = ''; }, [dom]);

  return (
    <>
      <ToneMapping />
      <LightingRig preset={LIGHT} shadow="none" />
      <mesh geometry={res.geos.floor} material={res.floor} rotation-x={-Math.PI / 2} position={[0.1, -2.05, 0.4]} scale={[5.5, 3.6, 1]} />
      {res.parts.map((p) => (
        <group
          key={p.id}
          ref={(g) => { if (g) groups.current.set(p.id, g); else groups.current.delete(p.id); }}
          position={p.base}
          onPointerOver={over(p.id)}
          onPointerOut={out}
          onClick={(e) => { e.stopPropagation(); onPick(p.id); }}
        >
          {p.meshes.map((x, i) => <mesh key={i} geometry={x.geo} material={x.mat} position={x.pos} rotation={x.rot} />)}
        </group>
      ))}
    </>
  );
}

.root {
  container-type: inline-size;
  width: 100%;
  align-self: stretch;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(15rem, 19rem);
  font-family: var(--s3-font-text, ui-sans-serif, system-ui, sans-serif);
  color: var(--s3-ink, #11110f);
}
.viewport {
  position: relative;
  min-height: clamp(320px, 58cqi, 540px);
  overflow: hidden;
  background: radial-gradient(100% 80% at 50% 45%, transparent 50%, var(--s3-surface-2, #e9e5da) 100%);
}
.viewport > [data-studio3-canvas] { position: absolute !important; inset: 0; }
.tag {
  position: absolute;
  left: 12px;
  top: 12px;
  margin: 0;
  padding: 5px 10px;
  border: 1px solid var(--s3-line, #11110f24);
  border-radius: 999px;
  background: var(--s3-surface, #fbf9f4);
  color: var(--s3-ink, #11110f);
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  pointer-events: none;
}

.panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: clamp(14px, 3cqi, 24px);
  border-left: 1px solid var(--s3-line, #11110f24);
}
.kicker {
  margin: 0;
  font-family: var(--s3-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--s3-ink-muted, #5c5a52);
}
.sliderRow { display: flex; align-items: baseline; justify-content: space-between; }
.value { font-family: var(--s3-font-mono, ui-monospace, monospace); font-size: 0.8125rem; font-variant-numeric: tabular-nums; }
.slider { width: 100%; height: 28px; margin: 0; accent-color: var(--s3-signal, #bf2f09); cursor: pointer; }
.slider:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }
.buttons { display: flex; gap: 8px; margin-bottom: 8px; }
.buttons button {
  flex: 1;
  min-height: 44px;
  border: 1px solid var(--s3-line-strong, #11110f);
  border-radius: 999px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
}
.buttons button:hover:not(:disabled) { background: var(--s3-ink, #11110f); color: var(--s3-surface, #fbf9f4); }
.buttons button:disabled { cursor: default; border-style: dashed; }
.buttons button:focus-visible { outline: 2px solid var(--s3-focus, #1d4ed8); outline-offset: 2px; }

.list { margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--s3-line, #11110f24); }
.list li { border-bottom: 1px solid var(--s3-line, #11110f24); }
.row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 44px;
  padding: 6px 8px 6px 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.row::before {
  content: '';
  position: absolute;
  left: -10px;
  top: 8px;
  bottom: 8px;
  width: 3px;
  border-radius: 2px;
